"""GENERATED by t15/make_figs_thesis.py from t8_figures.py (output redirect only).
T8.6: the two design sweeps at the worked example (lambda = c = 1, Sigma = 0.01)."""
import os

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

import sys
sys.path.insert(0, os.environ['CLS_DIR'])
from t8_common import C, COLS, FIG, LAM, SIG, coupling_sweep, g_star, prior_sweep, sigma2

F = SIG / LAM
INK, MUTED = "#222222", "#6b6b6b"
plt.rcParams.update({"font.size": 9, "axes.spines.top": False, "axes.spines.right": False,
                     "axes.edgecolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED})
fig, axes = plt.subplots(1, 3, figsize=(11, 3.6), constrained_layout=True)


def hline(ax, y, lab, ls, x_text, below=False):
    ax.axhline(y, color=MUTED, lw=0.9, ls=ls, zorder=1)
    if lab:
        ax.annotate(lab, (x_text, y), xytext=(2, -10 if below else 2), textcoords="offset points", color=INK, fontsize=8)


def vline(ax, x, lab, left=False):
    ax.axvline(x, color=COLS[1], lw=0.9, ls=":", zorder=1)
    if lab:
        ax.annotate(lab, (x, 1.0), xycoords=("data", "axes fraction"), xytext=(-14 if left else 3, -12),
                    textcoords="offset points", color=INK, fontsize=8)


def zoom(ax, f, x, Fv, s2, xv, xlab, pos=(0.42, 0.38, 0.54, 0.36)):
    """Inset around the minimum, where F and sigma*^2 are 0.5% apart."""
    ins = ax.inset_axes(list(pos)); ins.set_zorder(5); ins.patch.set_facecolor("white")
    ins.plot(x, f(x), color=COLS[0], lw=1.5, zorder=3)
    ins.axhline(Fv, color=MUTED, lw=0.8, ls="--"); ins.axhline(s2, color=MUTED, lw=0.8, ls=":")
    for v in xv:
        ins.axvline(v, color=COLS[1], lw=0.8, ls=":")
    ins.set_xscale("log"); ins.set_ylim(s2 - 0.15 * (Fv - s2), Fv + 0.6 * (Fv - s2))
    ins.text(x[0], Fv, r" $F$", va="bottom", fontsize=7, color=INK)
    ins.text(x[0], s2, r" $\sigma_\star^2$", va="bottom", fontsize=7, color=INK)
    ins.tick_params(labelsize=6); ins.yaxis.get_offset_text().set_fontsize(6)
    ins.set_title(xlab, fontsize=7, color=MUTED, loc="left")


th = np.logspace(-2, 5, 800)
for ax, Pi, tag in ((axes[0], 1.0, r"(a) prior sweep, $\Pi = 1$ (case P3)"), (axes[1], 500.0, r"(b) prior sweep, $\Pi = 500$ (case P1)")):
    f, _ = prior_sweep(Pi, C)
    ax.plot(th, f(th), color=COLS[0], lw=2, zorder=3)
    Gs = g_star(Pi)
    Vc = sigma2(C, Pi)
    hline(ax, F, r"$F$" if C <= Gs else "", "--", th[0])
    hline(ax, Vc, r"$V_c$", "-.", th[0])
    if C > Gs:
        hline(ax, Gs / Pi, "", ":", th[0])
        vline(ax, Pi * (C / Gs - 1), "")
        zoom(ax, f, np.logspace(0.5, 4.5, 400), F, Gs / Pi, [Pi * (C / Gs - 1)], r"zoom; dotted vertical: $\Pi_0^\star$")
    ax.set_xscale("log"); ax.set_yscale("log")
    ax.set_xlabel(r"prior precision $\Pi_0$"); ax.set_ylabel(r"$\sigma^2$")
    ax.text(0.02, -0.28, tag, transform=ax.transAxes, color=INK)

ax = axes[2]
cc = np.logspace(-4, 1, 800)
f, _ = coupling_sweep(1.0, 1.0)
ax.plot(cc, f(cc), color=COLS[0], lw=2, zorder=3)
Gs = g_star(1.0)
hline(ax, F, "", "--", cc[0])
hline(ax, Gs, "", ":", cc[0])
vline(ax, Gs / 0.5, r"$c^\star$", left=True)
vline(ax, 2 * F * 2.0, r"$c_F$")
zoom(ax, f, np.logspace(-3, -1, 400), F, Gs, [Gs / 0.5, 4 * F], r"zoom; dotted verticals: $c^\star$, $c_F$", pos=(0.16, 0.40, 0.44, 0.34))
ax.set_xscale("log"); ax.set_yscale("log")
ax.set_xlabel(r"coupling $c$"); ax.set_ylabel(r"$\sigma^2$")
ax.text(0.02, -0.28, r"(c) coupling sweep, $\Pi = \Pi_0 = 1$", transform=ax.transAxes, color=INK)
for a in axes:
    a.grid(True, which="major", color="#e6e6e6", lw=0.6)
p = os.path.join(os.environ["FIG_OUT"], 'B.3_design-sweeps.png')
fig.savefig(p, dpi=300)
print(f"T8.6: wrote {p}")
